async function i(r,s=5){const c=`feed_${r||"recent"}_${s}`;try{const t=localStorage.getItem(c);if(t){const a=JSON.parse(t);if(Date.now()-a.timestamp<36e5)return a.posts}}catch(t){console.warn("LocalStorage retrieval failed:",t)}const u=`${r?`/feeds/posts/default/-/${encodeURIComponent(r)}`:"/feeds/posts/default"}?alt=json&max-results=${s}`;try{const t=await fetch(u);if(!t.ok)throw new Error(`HTTP error! status: ${t.status}`);const n=((await t.json()).feed?.entry||[]).map(e=>{const f=e.title?.$t||"",m=e.link?.find(p=>p.rel==="alternate")?.href||"";let o=e.media$thumbnail?.url||"";o&&(o=o.replace(/\/s[0-9]+(-c)?\//,"/s640/"));const d=e.published?.$t||"",l=e.summary?.$t||e.content?.$t||"",h=l.replace(/<[^>]*>/g,"").trim().substring(0,150)+(l.length>150?"...":"");return{title:f,url:m,thumb:o,date:d,summary:h}});try{const e={timestamp:Date.now(),posts:n};localStorage.setItem(c,JSON.stringify(e))}catch(e){console.warn("Failed to cache feed to LocalStorage:",e)}return n}catch(t){console.error("Failed to fetch Blogger JSON feed:",t);try{const a=localStorage.getItem(c);if(a)return JSON.parse(a).posts}catch{}return[]}}async function S(r,s=5){return i(r,s)}async function w(r=5){return i(null,r)}export{i as fetchBloggerFeed,S as getPostsByLabel,w as getRecentPosts};
